export const today = () => new Date().toISOString().slice(0,10);
export const monthOf = d => d.slice(0,7);
export const uid = () => globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2);
export const categories = ['Logement','Alimentation','Transport','Communication','Santé et protection','Vie de couple','Obligations','Imprévus','Shopping','Loisirs individuels','Abonnements personnels','Santé individuelle','Autres'];
export const subcategories = {Logement:['Loyer','Électricité','Eau','Entretien du logement','Équipements domestiques'],Alimentation:['Courses','Restaurants en couple','Livraisons'],Transport:['Déplacements communs','Carburant','Entretien du véhicule','Transport individuel'],Communication:['Internet','Téléphone partagé','Abonnements communs'],'Santé et protection':['Assurance','Dépenses médicales communes','Dépenses familiales'],'Vie de couple':['Sorties','Rendez-vous','Cadeaux communs','Anniversaires','Vacances'],Obligations:['Crédits communs','Aide familiale commune','Charges diverses'],Imprévus:['Réparations','Urgences','Dépenses exceptionnelles']};
export const types = {income:'Revenu',expense:'Dépense',saving:'Versement d’épargne',transfer:'Transfert interne',reimbursement:'Remboursement entre partenaires',principal:'Remboursement de capital',interest:'Intérêts et frais'};
export const defaults = () => ({version:1,profile:{p1:'',p2:'',salary1:0,salary2:0,currency:'XOF',start:today(),mode:'mixed',split:'proportional',percent:50,goals1:'',goals2:'',goalsShared:'',share1:true,share2:true,details1:false,details2:false},transactions:[],goals:[],events:[],budgets:{},categories:[...categories],theme:'light'});
export const moneyUnit = c => ['XOF','XAF','JPY'].includes(c)?1:100;
export const round = (n,c='XOF') => Math.round((n+Number.EPSILON)*moneyUnit(c))/moneyUnit(c);
export const sum = (a,fn=x=>x.amount) => a.reduce((s,x)=>s+Number(fn(x)||0),0);
export const shiftMonth = (m,n) => {const [y,k]=m.split('-').map(Number); return new Date(Date.UTC(y,k-1+n,1)).toISOString().slice(0,7);};
export function incomeBasis(s,m){ const t=s.transactions.filter(t=>t.type==='income'&&t.status==='paid'&&monthOf(t.date)===m); return [sum(t.filter(t=>t.owner==='p1')),sum(t.filter(t=>t.owner==='p2'))]; }
export function ratio(s,m,method=s.profile.split,percent=s.profile.percent){if(method==='equal')return .5;if(method==='custom')return Math.max(0,Math.min(100,Number(percent)))/100;let [a,b]=incomeBasis(s,m);if(!a&&!b){a=Number(s.profile.salary1);b=Number(s.profile.salary2);}return a+b?a/(a+b):.5;}
export function splitAmount(s,t){const r=ratio(s,monthOf(t.date),t.split==='default'?s.profile.split:t.split,t.split==='default'?s.profile.percent:t.percent);const a=round(t.amount*r,s.profile.currency);return [a,round(t.amount-a,s.profile.currency)];}
export const isCharge = t => ['expense','interest','principal'].includes(t.type);
export function metrics(s,m,filter={}){
 const all=s.transactions.filter(t=>monthOf(t.date)===m);
 const chosen=all.filter(t=>(!filter.partner||t.owner===filter.partner||t.scope===filter.partner||t.payer===filter.partner)&&(!filter.category||t.category===filter.category)&&(!filter.type||t.type===filter.type));
 const paid=chosen.filter(t=>t.status==='paid'),incomes=paid.filter(t=>t.type==='income'),charges=paid.filter(isCharge),spending=charges.filter(t=>t.type!=='principal'),savings=paid.filter(t=>t.type==='saving');
 const income=sum(incomes),expense=sum(spending),principal=sum(charges.filter(t=>t.type==='principal')),saved=sum(savings),shared=sum(spending.filter(t=>t.scope==='shared')),personal=sum(spending.filter(t=>t.scope!=='shared'));
 const visiblePersonal=sum(spending.filter(t=>t.scope!=='shared'&&s.profile['share'+t.scope.slice(1)]));
 const visibleSaving=sum(savings.filter(t=>t.scope==='shared'||s.profile['share'+t.scope.slice(1)]));
 return {all,chosen,paid,income,expense,principal,saved,shared,personal,visiblePersonal,visibleSaving,sharedSaving:sum(savings.filter(t=>t.scope==='shared')),personalSaving:sum(savings.filter(t=>t.scope!=='shared')),available:round(income-expense-principal-saved,s.profile.currency),rate:income?saved/income*100:0,pending:sum(chosen.filter(t=>t.status==='planned'&&isCharge(t))),fixed:sum(incomes.filter(t=>t.frequency==='monthly')),variable:sum(incomes.filter(t=>t.frequency!=='monthly'))};
}
export function settlement(s,m){
 const all=s.transactions.filter(t=>monthOf(t.date)===m), paid=all.filter(t=>isCharge(t)&&t.scope==='shared'&&t.status==='paid');
 let expected=[0,0],actual=[0,0],common=0,commonShare=[0,0];
 paid.forEach(t=>{const shares=splitAmount(s,t);expected=expected.map((x,i)=>x+shares[i]);if(t.payer==='common'){common+=t.amount;commonShare=commonShare.map((x,i)=>x+shares[i]);}else actual[t.payer==='p1'?0:1]+=t.amount;});
 let transfers=0;all.filter(t=>t.type==='reimbursement'&&t.status==='paid').forEach(t=>{if(t.from==='p1'&&t.to==='p2')transfers+=t.amount;if(t.from==='p2'&&t.to==='p1')transfers-=t.amount;});
 const balance=round(expected[0]-commonShare[0]-actual[0]-transfers,s.profile.currency);
 return {expected:expected.map(x=>round(x,s.profile.currency)),actual:actual.map(x=>round(x,s.profile.currency)),common,commonShare,transfers,balance,amount:Math.abs(balance),from:balance>=0?'p1':'p2',to:balance>=0?'p2':'p1',total:sum(paid)};
}
export function goalProgress(s,g){const payments=s.transactions.filter(t=>t.type==='saving'&&t.goalId===g.id&&t.status==='paid');const saved=round(Number(g.opening)+sum(payments),s.profile.currency),remaining=Math.max(0,g.target-saved);const months=g.monthly>0?Math.ceil(remaining/g.monthly):null;return {saved,remaining,percent:g.target?Math.min(100,saved/g.target*100):0,months,estimated:months===null?null:shiftMonth(monthOf(today()),months),payments,p1:sum(payments.filter(t=>t.owner==='p1')),p2:sum(payments.filter(t=>t.owner==='p2'))};}
export function budgetFor(s,m){return s.budgets[m]||{shared:0,p1:0,p2:0,saving:0,rollover:false,categories:{}};}
export function carry(s,m,depth=0){const b=budgetFor(s,m);if(!b.rollover||depth>120||m<=monthOf(s.profile.start))return 0;const prev=shiftMonth(m,-1),p=budgetFor(s,prev),v=metrics(s,prev);return Math.max(0,Number(p.shared)+Number(p.p1)+Number(p.p2)+carry(s,prev,depth+1)-v.expense-v.principal);}
export const budgetTotal=(s,m)=>{const b=budgetFor(s,m);return Number(b.shared)+Number(b.p1)+Number(b.p2)+carry(s,m);};
export function nextOccurrence(t){const [y,m,d]=t.date.split('-').map(Number);const last=new Date(Date.UTC(y,m+1,0)).getUTCDate();return `${shiftMonth(monthOf(t.date),1)}-${String(Math.min(d,last)).padStart(2,'0')}`;}
export function validData(d){
 const fail=()=>{throw new Error('Le fichier ne correspond pas à une sauvegarde valide de Notre Budget à Deux.');};
 if(!d||d.version!==1||!d.profile||!Array.isArray(d.transactions)||!Array.isArray(d.goals)||!Array.isArray(d.events)||!Array.isArray(d.categories)||!d.budgets||typeof d.budgets!=='object')fail();
 const finite=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=1e14,txt=x=>typeof x==='string'&&x.length<=5000,date=x=>txt(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(Date.parse(x))&&new Date(x).toISOString().slice(0,10)===x;
 const p=d.profile;if(!['XOF','XAF','EUR','USD','CAD','GBP','CHF','MAD'].includes(p.currency)||!['mixed','separate','joint'].includes(p.mode)||!['equal','proportional','custom'].includes(p.split)||!finite(p.salary1)||!finite(p.salary2)||!finite(p.percent)||p.percent>100||!date(p.start)||!['p1','p2','goals1','goals2','goalsShared'].every(k=>txt(p[k]))||!['share1','share2','details1','details2'].every(k=>typeof p[k]==='boolean'))fail();
 if(d.transactions.length>50000||d.goals.length>1000||d.events.length>5000||d.categories.length>100||!d.categories.every(c=>txt(c)&&!['__proto__','prototype','constructor'].includes(c))||!['light','dark'].includes(d.theme))fail();
 const ids=new Set();for(const t of d.transactions){if(!txt(t.id)||ids.has(t.id)||!types[t.type]||!finite(t.amount)||t.amount===0||!date(t.date)||!['paid','planned'].includes(t.status)||!['shared','p1','p2'].includes(t.scope)||!['p1','p2'].includes(t.owner)||!['p1','p2','common'].includes(t.payer)||!['p1','p2','common'].includes(t.from)||!['p1','p2','common'].includes(t.to)||!['default','equal','proportional','custom'].includes(t.split)||!finite(t.percent)||t.percent>100||!['once','monthly','variable'].includes(t.frequency)||!['description','category','subcategory','source','receipt','goalId','beneficiary'].every(k=>txt(t[k])))fail();ids.add(t.id);}
 const gids=new Set();for(const g of d.goals){if(!txt(g.id)||gids.has(g.id)||!txt(g.name)||!date(g.deadline)||!['shared','p1','p2'].includes(g.scope)||!finite(g.opening)||(!finite(g.target)||g.target===0)||!finite(g.monthly)||!finite(g.percent)||g.percent>100||!['equal','proportional','custom'].includes(g.split)||!['high','medium','low'].includes(g.priority))fail();gids.add(g.id);}
 if(d.transactions.some(t=>t.goalId&&!gids.has(t.goalId)))fail();
 for(const e of d.events)if(!txt(e.id)||!txt(e.name)||!date(e.date)||!['shared','p1','p2'].includes(e.scope)||!finite(e.amount)||typeof e.recurring!=='boolean')fail();
 for(const [m,b] of Object.entries(d.budgets)){if(!/^\d{4}-\d{2}$/.test(m)||Number(m.slice(5))<1||Number(m.slice(5))>12||!b||!['shared','p1','p2','saving'].every(k=>finite(b[k]))||typeof b.rollover!=='boolean'||!b.categories||typeof b.categories!=='object'||Object.values(b.categories).some(n=>!finite(n)))fail();}
 return JSON.parse(JSON.stringify(d));
}
export function demo(){const s=defaults(),m=monthOf(today());s.profile={...s.profile,p1:'Camille',p2:'Alex',salary1:600000,salary2:400000};const t=(type,amount,day,extra={})=>({id:uid(),type,amount,date:`${m}-${String(day).padStart(2,'0')}`,scope:'shared',owner:'p1',payer:'p1',from:'p1',to:'p2',category:'Autres',subcategory:'',description:'',source:'',status:'paid',frequency:'once',split:'default',percent:50,receipt:'',goalId:'',beneficiary:'',...extra});s.transactions=[t('income',600000,1,{owner:'p1',source:'Salaire principal',description:'Salaire de Camille',frequency:'monthly'}),t('income',400000,2,{owner:'p2',source:'Salaire principal',description:'Salaire d’Alex',frequency:'monthly'}),t('expense',240000,3,{category:'Logement',subcategory:'Loyer',description:'Loyer du mois'}),t('expense',65000,6,{payer:'p2',category:'Alimentation',subcategory:'Courses',description:'Courses du foyer'}),t('expense',28000,8,{category:'Communication',description:'Internet et abonnements'}),t('expense',40000,10,{payer:'p2',category:'Transport',description:'Déplacements communs'}),t('expense',22000,12,{category:'Vie de couple',description:'Dîner à deux'}),t('expense',35000,14,{scope:'p1',category:'Loisirs individuels',description:'Loisirs personnels'}),t('expense',25000,16,{scope:'p2',payer:'p2',owner:'p2',category:'Shopping',description:'Achats personnels'})];s.goals=[{id:'demo-emergency',name:'Notre fonds de sécurité',target:1200000,opening:420000,deadline:shiftMonth(m,8)+'-01',priority:'high',monthly:85000,scope:'shared',split:'proportional',percent:50},{id:'demo-travel',name:'Une escapade à deux',target:600000,opening:180000,deadline:shiftMonth(m,6)+'-01',priority:'medium',monthly:50000,scope:'shared',split:'equal',percent:50}];s.transactions.push(t('saving',51000,5,{goalId:'demo-emergency'}),t('saving',34000,5,{owner:'p2',payer:'p2',goalId:'demo-emergency'}),t('saving',25000,7,{goalId:'demo-travel'}),t('saving',25000,7,{owner:'p2',payer:'p2',goalId:'demo-travel'}));s.budgets[m]={shared:500000,p1:80000,p2:70000,saving:135000,rollover:false,categories:{Logement:260000,Alimentation:100000,Transport:60000,'Vie de couple':40000,Communication:30000,Imprévus:10000}};s.events=[{id:uid(),name:'Notre rendez-vous budget',date:m+'-25',scope:'shared',amount:0,recurring:true}];return s;}
